//! Reference vectors for `madmom_audio::stft`.
//!
//! Generated by `tools/gen_audio_vectors.py` — do not edit by hand. The numbers
//! are madmom's own output for the same input, including the cases the golden
//! STFT dump does not cover: circular shifting, an FFT longer than the frame,
//! the Nyquist bin and float frames (no window scaling).

#![allow(clippy::excessive_precision)]

use madmom_audio::stft::{fft_frequencies, hamming, hanning, stft};
use num_complex::Complex32;

fn complex(values: &[(f32, f32)]) -> Vec<Complex32> {
    values
        .iter()
        .map(|(re, im)| Complex32::new(*re, *im))
        .collect()
}

fn close_real(got: &[f64], expected: &[f64], atol: f64, what: &str) {
    assert_eq!(got.len(), expected.len(), "{what}: length differs");
    for (index, (got, expected)) in got.iter().zip(expected).enumerate() {
        assert!(
            (got - expected).abs() <= atol,
            "{what}: index {index}: got {got}, reference {expected}"
        );
    }
}

fn close_complex(got: &[Complex32], expected: &[Complex32], atol: f32, what: &str) {
    assert_eq!(got.len(), expected.len(), "{what}: length differs");
    for (index, (got, expected)) in got.iter().zip(expected).enumerate() {
        assert!(
            (*got - *expected).norm() <= atol,
            "{what}: index {index}: got {got}, reference {expected}"
        );
    }
}

